window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-d60510cff085a743"]={"versions": [{"id": "FIG-d60510cff085a743", "releases": ["R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-Anwendungsfalldiagramm (Use Case Diagram) mit geschachtelten Systemgrenzen (System Boundary: <code>Adaptive Platform</code>, Sub-System / Functional Cluster: <code>Raw Data Stream</code>).</li>\n<li><strong>Funktionale Einordnung:</strong> AUTOSAR Adaptive Platform (Release R24-11), Spezifikation <code>AUTOSAR_AP_EXP_SWArchitecture</code>.</li>\n<li><strong>Technischer Zweck:</strong> Definition der primären Interaktionsmuster für den Cluster <em>Raw Data Stream</em>. Der Mechanismus dient dem transporteffizienten, serialisierungsfreien Streaming von Rohdaten (z. B. Audio/Video, Radardaten, Sensor-Rohströme oder Diagnose-Bulk-Data) mit hohem Durchsatz und minimalem Overhead an den Standard-Service-Interfaces (<code>ara::com</code>) vorbei.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Akteure (Actors):</strong></li>\n<li><code>Adaptive Application</code> (<code>(from Actors)</code>): Primärer, aktiver Akteur im Userspace, der den Kommunikationszyklus aus Applikationssicht steuert.</li>\n<li><code>Operating System</code> (<code>(from Actors)</code>): Sekundärer, passiv/unterstützender Akteur (POSIX OS-Kernel / Treiber / Netzwerk-Stack).</li>\n<li><strong>Systemgrenzen & Subsysteme:</strong></li>\n<li><code>Adaptive Platform</code>: Umfassender Plattformkontext der AUTOSAR-AP-Middleware.</li>\n<li><code>Raw Data Stream</code>: Spezifischer Funktionscluster / Middleware-Dienst zur Kapselung und Abstraktion der Datenstromübertragung.</li>\n<li><strong>Use Cases (Anwendungsfälle):</strong></li>\n<li><code>Send Raw Data Stream</code>: Kontinuierliches Senden unstrukturierter Byteströme in den Zielkanal.</li>\n<li><code>Receive Raw Data Stream</code>: Kontinuierliches Empfangen unstrukturierter Byteströme aus der Quelle.</li>\n<li><strong>Stereotypen & Beziehungen:</strong></li>\n<li><code>«aapTriggers»</code>: Gerichtete Assoziation von <code>Adaptive Application</code> auf beide Use Cases. Kennzeichnet die AA als initiierenden Auslöser für Aufbau, Datentransfer und Terminierung.</li>\n<li><code>«aapParticipates»</code>: Assoziation zwischen <code>Operating System</code> und beiden Use Cases. Kennzeichnet das OS als ausführende/teilnehmende Entität, welche die zugrundeliegenden I/O- und Transportressourcen bereitstellt.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\">\n<li><strong>Sende-Pfad (<code>Send Raw Data Stream</code>):</strong></li>\n</ul>\n<ol class=\"fig-list\">\n<li><em>Initialisierung/Trigger:</em> Die AA initiiert den Stream über die plattformspezifische API (z. B. Stream-Deskriptor, Socket- oder Pipe-Abstraktion).</li>\n<li><em>Datenübergabe:</em> Die AA übergibt kontinuierlich Puffersegmente (Payload ohne Serialisierungs-Overhead) an den Cluster.</li>\n<li><em>OS-Partizipation:</em> Der Cluster delegiert das Routing an das OS (z. B. über POSIX-Socket-I/O, Shared Memory oder Zero-Copy-IPC), welches die Daten auf physische Schnittstellen oder interne IPC-Kanäle leitet.</li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Empfangs-Pfad (<code>Receive Raw Data Stream</code>):</strong></li>\n</ul>\n<ol class=\"fig-list\">\n<li><em>Bereitstellung/Trigger:</em> Die AA registriert Listener, Callback-Handler oder Polling-Mechanismen auf den Datenstrom.</li>\n<li><em>OS-Signalisierung:</em> Das OS nimmt eingehende Frames auf Treiberebene entgegen, puffert diese und signalisiert Datenverfügbarkeit (z. B. via Event-Notification, <code>epoll</code>/<code>poll</code>).</li>\n<li><em>Zustellung:</em> Der Cluster stellt die Rohdaten via Zero-Copy-Mechanismen oder Bytestream-Reader der AA im Userspace bereit.</li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Synchronizität & Latenz:</strong> I/O-Pfade sind primär asynchron bzw. non-blocking ausgelegt, um Blockaden im deterministischen Scheduling der AA bei Burst-Traffic zu verhindern.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>API-Vertrag & Abgrenzung:</strong></li>\n<li>Entwickler dürfen für diesen Use Case keine SOME/IP-Serialisierung oder ereignisbasierte <code>ara::com</code>-Proxy/Skeleton-Bindung erwarten; Datenformate müssen applikationsseitig selbst validiert und interpretiert werden.</li>\n<li>Pufferübergaben nutzen typsichere Bytestrom-Container (z. B. <code>ara::core::Span&lt;const std::uint8_t&gt;</code>).</li>\n<li><strong>Plattform- & OS-Konfiguration:</strong></li>\n<li>Das zugrundeliegende OS muss POSIX-konforme Stream- bzw. Puffer-Mechanismen mit hinreichender Bandbreite und Puffergrößen (z. B. Socket Receive/Send Buffer) garantieren.</li>\n<li>Das <em>Execution Manifest</em> der AA muss die entsprechenden Berechtigungen (Resource/Network Limits, POSIX-Capabilities, Access Control Lists) für die jeweilige OS-Ressource deklarieren.</li>\n</ul>"}, {"id": "FIG-e6deb51cd0888b04", "releases": ["R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-Anwendungsfalldiagramm (Use Case Diagram) mit geschachtelten Systemgrenzen (System Boundary: <code>Adaptive Platform</code>, Sub-System / Functional Cluster: <code>Raw Data Stream</code>).</li>\n<li><strong>Funktionale Einordnung:</strong> AUTOSAR Adaptive Platform (Release R24-11), Spezifikation <code>AUTOSAR_AP_EXP_SWArchitecture</code>.</li>\n<li><strong>Technischer Zweck:</strong> Definition der primären Interaktionsmuster für den Cluster <em>Raw Data Stream</em>. Der Mechanismus dient dem transporteffizienten, serialisierungsfreien Streaming von Rohdaten (z. B. Audio/Video, Radardaten, Sensor-Rohströme oder Diagnose-Bulk-Data) mit hohem Durchsatz und minimalem Overhead an den Standard-Service-Interfaces (<code>ara::com</code>) vorbei.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Akteure (Actors):</strong></li>\n<li><code>Adaptive Application</code> (<code>(from Actors)</code>): Primärer, aktiver Akteur im Userspace, der den Kommunikationszyklus aus Applikationssicht steuert.</li>\n<li><code>Operating System</code> (<code>(from Actors)</code>): Sekundärer, passiv/unterstützender Akteur (POSIX OS-Kernel / Treiber / Netzwerk-Stack).</li>\n<li><strong>Systemgrenzen & Subsysteme:</strong></li>\n<li><code>Adaptive Platform</code>: Umfassender Plattformkontext der AUTOSAR-AP-Middleware.</li>\n<li><code>Raw Data Stream</code>: Spezifischer Funktionscluster / Middleware-Dienst zur Kapselung und Abstraktion der Datenstromübertragung.</li>\n<li><strong>Use Cases (Anwendungsfälle):</strong></li>\n<li><code>Send Raw Data Stream</code>: Kontinuierliches Senden unstrukturierter Byteströme in den Zielkanal.</li>\n<li><code>Receive Raw Data Stream</code>: Kontinuierliches Empfangen unstrukturierter Byteströme aus der Quelle.</li>\n<li><strong>Stereotypen & Beziehungen:</strong></li>\n<li><code>«aapTriggers»</code>: Gerichtete Assoziation von <code>Adaptive Application</code> auf beide Use Cases. Kennzeichnet die AA als initiierenden Auslöser für Aufbau, Datentransfer und Terminierung.</li>\n<li><code>«aapParticipates»</code>: Assoziation zwischen <code>Operating System</code> und beiden Use Cases. Kennzeichnet das OS als ausführende/teilnehmende Entität, welche die zugrundeliegenden I/O- und Transportressourcen bereitstellt.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\">\n<li><strong>Sende-Pfad (<code>Send Raw Data Stream</code>):</strong></li>\n</ul>\n<ol class=\"fig-list\">\n<li><em>Initialisierung/Trigger:</em> Die AA initiiert den Stream über die plattformspezifische API (z. B. Stream-Deskriptor, Socket- oder Pipe-Abstraktion).</li>\n<li><em>Datenübergabe:</em> Die AA übergibt kontinuierlich Puffersegmente (Payload ohne Serialisierungs-Overhead) an den Cluster.</li>\n<li><em>OS-Partizipation:</em> Der Cluster delegiert das Routing an das OS (z. B. über POSIX-Socket-I/O, Shared Memory oder Zero-Copy-IPC), welches die Daten auf physische Schnittstellen oder interne IPC-Kanäle leitet.</li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Empfangs-Pfad (<code>Receive Raw Data Stream</code>):</strong></li>\n</ul>\n<ol class=\"fig-list\">\n<li><em>Bereitstellung/Trigger:</em> Die AA registriert Listener, Callback-Handler oder Polling-Mechanismen auf den Datenstrom.</li>\n<li><em>OS-Signalisierung:</em> Das OS nimmt eingehende Frames auf Treiberebene entgegen, puffert diese und signalisiert Datenverfügbarkeit (z. B. via Event-Notification, <code>epoll</code>/<code>poll</code>).</li>\n<li><em>Zustellung:</em> Der Cluster stellt die Rohdaten via Zero-Copy-Mechanismen oder Bytestream-Reader der AA im Userspace bereit.</li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Synchronizität & Latenz:</strong> I/O-Pfade sind primär asynchron bzw. non-blocking ausgelegt, um Blockaden im deterministischen Scheduling der AA bei Burst-Traffic zu verhindern.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>API-Vertrag & Abgrenzung:</strong></li>\n<li>Entwickler dürfen für diesen Use Case keine SOME/IP-Serialisierung oder ereignisbasierte <code>ara::com</code>-Proxy/Skeleton-Bindung erwarten; Datenformate müssen applikationsseitig selbst validiert und interpretiert werden.</li>\n<li>Pufferübergaben nutzen typsichere Bytestrom-Container (z. B. <code>ara::core::Span&lt;const std::uint8_t&gt;</code>).</li>\n<li><strong>Plattform- & OS-Konfiguration:</strong></li>\n<li>Das zugrundeliegende OS muss POSIX-konforme Stream- bzw. Puffer-Mechanismen mit hinreichender Bandbreite und Puffergrößen (z. B. Socket Receive/Send Buffer) garantieren.</li>\n<li>Das <em>Execution Manifest</em> der AA muss die entsprechenden Berechtigungen (Resource/Network Limits, POSIX-Capabilities, Access Control Lists) für die jeweilige OS-Ressource deklarieren.</li>\n</ul>"}], "trans": [{"from": "FIG-d60510cff085a743", "to": "FIG-e6deb51cd0888b04", "fr": "R24-11", "tr": "R25-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
